            self.column_values = &.{};
            gpa.free(self.leaves);
            self.leaves = &.{};
            gpa.free(self.row.values);
            self.row.values = &.{};
            _ = self.arena.reset(.retain_capacity);
            self.cursor = 0;
            self.num_rows = 0;
        }
    };

