 'values[i] = .{ .bytes_val = try value_mod.dupeBytes(allocator, "") };',
 'values[i] = .{ .bytes_val = try value_mod.dupeBytes(allocator, ba.value) };',
]
out=[]
changed=[]
for i,l in enumerate(lines):
    st=l.strip()
    if st in pats:
        ctxt='\n'.join(lines[max(0,i-12):i])
        # skip fixed-len dict site (uses fixed_byte_array_dict)
        if 'fixed_byte_array_dict' in '\n'.join(lines[max(0,i-3):i]):
            out.append(l); continue
        l=l.replace('value_mod.dupeBytes','takeBytes'); changed.append(i+1)
    out.append(l)
open(p,'w',encoding='utf-8',newline='\n').write('\n'.join(out))
print(changed)
